CREATE OR REPLACE FUNCTION public.actualizar_detalles_queja(p_queja_id uuid, p_categoria text DEFAULT NULL::text, p_prioridad text DEFAULT NULL::text, p_responsable_id uuid DEFAULT NULL::uuid, p_notas text DEFAULT NULL::text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_queja public.quejas;
  v_dias integer;
BEGIN
  IF NOT public.app_es_staff() THEN RAISE EXCEPTION 'No autorizado'; END IF;

  SELECT * INTO v_queja FROM public.quejas WHERE id = p_queja_id FOR UPDATE;
  IF v_queja.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada'; END IF;

  IF p_prioridad IS NOT NULL THEN
    SELECT dias_vencimiento INTO v_dias
    FROM public.sla_config WHERE proceso = 'quejas' AND prioridad = btrim(p_prioridad) LIMIT 1;
  END IF;

  UPDATE public.quejas
  SET categoria = COALESCE(nullif(btrim(p_categoria), ''), categoria),
      prioridad = COALESCE(nullif(btrim(p_prioridad), ''), prioridad),
      responsable_id = COALESCE(p_responsable_id, responsable_id),
      notas = COALESCE(p_notas, notas),
      fecha_sla = CASE WHEN p_prioridad IS NULL THEN fecha_sla
        ELSE COALESCE(fecha, now()) + make_interval(days => COALESCE(v_dias, 7)) END
  WHERE id = p_queja_id
  RETURNING * INTO v_queja;

  RETURN v_queja;
END;
$function$

CREATE OR REPLACE FUNCTION public.crear_queja_interna(p_cliente_nombre text, p_email_cliente text, p_categoria text, p_descripcion text, p_prioridad text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_queja public.quejas;
  v_dias integer;
BEGIN
  IF NOT public.app_es_staff() THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  IF btrim(COALESCE(p_cliente_nombre, '')) = '' OR btrim(COALESCE(p_categoria, '')) = '' OR btrim(COALESCE(p_prioridad, '')) = '' THEN
    RAISE EXCEPTION 'Cliente, categoría y prioridad son obligatorios';
  END IF;

  SELECT dias_vencimiento INTO v_dias
  FROM public.sla_config
  WHERE proceso = 'quejas' AND prioridad = btrim(p_prioridad)
  LIMIT 1;

  INSERT INTO public.quejas (
    folio, cliente_nombre, email_cliente, categoria, descripcion,
    prioridad, estado, fecha, fecha_sla
  ) VALUES (
    public.generar_folio_queja(), btrim(p_cliente_nombre), nullif(btrim(p_email_cliente), ''),
    btrim(p_categoria), nullif(btrim(p_descripcion), ''), btrim(p_prioridad),
    'Recibido', now(), now() + make_interval(days => COALESCE(v_dias, 7))
  ) RETURNING * INTO v_queja;

  INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
  VALUES (now(), public.app_usuario_actual_id(), 'crear', 'quejas', 'Queja interna ' || v_queja.folio || ' creada');

  RETURN v_queja;
END;
$function$

CREATE OR REPLACE FUNCTION public.crear_queja_interna_con_atributos(p_cliente_nombre text, p_email_cliente text, p_categoria text, p_descripcion text, p_prioridad text, p_tipo text, p_area_afectada text, p_fecha_recepcion_gc date, p_numero_oficio_resolucion text, p_observaciones text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_queja public.quejas;
  v_dias integer;
BEGIN
  IF NOT public.app_es_staff() THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF btrim(coalesce(p_cliente_nombre, '')) = ''
     OR btrim(coalesce(p_categoria, '')) = ''
     OR btrim(coalesce(p_prioridad, '')) = ''
     OR btrim(coalesce(p_tipo, '')) = ''
     OR btrim(coalesce(p_area_afectada, '')) = '' THEN
    RAISE EXCEPTION 'Nombre, tipo, área afectada, categoría y prioridad son obligatorios';
  END IF;

  SELECT dias_vencimiento INTO v_dias
  FROM public.sla_config
  WHERE proceso = 'quejas' AND prioridad = btrim(p_prioridad)
  LIMIT 1;

  INSERT INTO public.quejas (
    folio, cliente_nombre, email_cliente, categoria, descripcion,
    prioridad, estado, fecha, fecha_sla, tipo, area_afectada,
    fecha_recepcion_gc, numero_oficio_resolucion, observaciones
  ) VALUES (
    public.generar_folio_queja(), btrim(p_cliente_nombre),
    nullif(btrim(p_email_cliente), ''), btrim(p_categoria),
    nullif(btrim(p_descripcion), ''), btrim(p_prioridad),
    'Recibido', now(), now() + make_interval(days => coalesce(v_dias, 7)),
    btrim(p_tipo), btrim(p_area_afectada),
    coalesce(p_fecha_recepcion_gc, timezone('America/Costa_Rica', now())::date),
    nullif(btrim(p_numero_oficio_resolucion), ''),
    nullif(btrim(p_observaciones), '')
  ) RETURNING * INTO v_queja;

  INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
  VALUES (now(), public.app_usuario_actual_id(), 'crear', 'quejas',
    'Queja interna ' || v_queja.folio || ' creada');
  RETURN v_queja;
END;
$function$

CREATE OR REPLACE FUNCTION public.crear_queja_publica(p_token text, p_cliente_nombre text, p_email_cliente text, p_telefono text, p_categoria text, p_descripcion text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_form formularios_publicos;
  v_folio text;
BEGIN
  SELECT * INTO v_form
  FROM formularios_publicos
  WHERE token = p_token AND activo = true
  LIMIT 1;

  IF v_form.id IS NULL THEN
    RAISE EXCEPTION 'El enlace no es válido o ya no está disponible';
  END IF;

  IF p_cliente_nombre IS NULL OR btrim(p_cliente_nombre) = '' THEN
    RAISE EXCEPTION 'El nombre del quejoso es obligatorio';
  END IF;

  v_folio := generar_folio_queja();

  INSERT INTO quejas (
    folio, cliente_nombre, email_cliente, telefono,
    categoria, descripcion, estado, fecha
  ) VALUES (
    v_folio,
    btrim(p_cliente_nombre),
    p_email_cliente,
    p_telefono,
    p_categoria,
    p_descripcion,
    'Recibido',
    now()
  );

  RETURN v_folio;
END;
$function$

CREATE OR REPLACE FUNCTION public.crear_queja_publica_con_atributos(p_token text, p_cliente_nombre text, p_email_cliente text, p_telefono text, p_tipo text, p_descripcion text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_folio text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.formularios_publicos
    WHERE token = p_token AND activo = true AND modulo = 'quejas'
  ) THEN
    RAISE EXCEPTION 'El enlace no es válido o ya no está disponible';
  END IF;
  IF btrim(coalesce(p_cliente_nombre, '')) = ''
     OR btrim(coalesce(p_tipo, '')) = ''
     OR btrim(coalesce(p_descripcion, '')) = '' THEN
    RAISE EXCEPTION 'Nombre, tipo y descripción son obligatorios';
  END IF;
  IF p_tipo NOT IN ('Queja', 'Observación', 'Sugerencia', 'Denuncia', 'Reclamo', 'Felicitación') THEN
    RAISE EXCEPTION 'El tipo de registro no es válido';
  END IF;

  v_folio := public.generar_folio_queja();
  INSERT INTO public.quejas (
    folio, cliente_nombre, email_cliente, telefono, categoria, tipo,
    descripcion, estado, fecha, fecha_recepcion_gc
  ) VALUES (
    v_folio, btrim(p_cliente_nombre), nullif(btrim(p_email_cliente), ''),
    nullif(btrim(p_telefono), ''), btrim(p_tipo), btrim(p_tipo),
    btrim(p_descripcion), 'Recibido', now(),
    timezone('America/Costa_Rica', now())::date
  );
  RETURN v_folio;
END;
$function$

